    [6215]={name="Balanced Fighting Stick",quality=2,ilvl=13,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: \"Hogger\"'. Pick it over the other reward choices.",zone="Elwynn Forest",questName="Wanted:  \"Hogger\"",lore="Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."},
    [6220]={name="Meteor Shard",quality=3,ilvl=28,reqLevel=23,sourceType="boss_drop",instructions="Drops from Archmage Arugal.",zone="Shadowfang Keep",npc="Archmage Arugal",proc="Chance on hit: Blasts a target for 42 Fire damage."},
    [6223]={name="Crest of Darkshire",quality=2,ilvl=35,reqLevel=20,sourceType="quest_reward",instructions="Reward from the quest 'Bride of the Embalmer'. Starts with Lord Ello Ebonlocke in Duskwood. Objective: Find Eliza's grave. Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.",zone="Duskwood",questName="Bride of the Embalmer",lore="The Embalmer is a name told in one of our children's stories. He was a kindly alchemist, driven mad by the death of his wife, Eliza. To restore her, he used dark magic to place his own heart within the bosom of his dead spouse."},
