    [19608]={name="Vision of Voodress",quality=3,ilvl=68,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Vision of Voodress'. Starts with Maywiki of Zuldazar in Stranglethorn Vale. Objective: ProgressSha-mon! Maywiki make a joke!&lt;Maywiki laughs.&gt;So, you been using the spirits and elements against our enemies in Zul'Gurub, eh? Spirits be praised!Maywiki gonna brighten your orb. Give it here, &lt;name&gt;.",zone="Zul'Gurub",questName="Vision of Voodress"},
